  async function streamInto(task, input, textarea, btn2) {
    const original = btn2?.innerHTML;
    if (btn2) {
      btn2.disabled = true;
      btn2.replaceChildren(glyph("loading"), span(t("Writing\u2026")));
    }
    const prev = textarea.value;
    const setComposer = (v3) => {
      textarea.value = v3;
      textarea.dispatchEvent(new Event("input", { bubbles: true }));
    };
    setComposer("");
    let got = false;
    const gone = () => !textarea.isConnected;
    const res = await streamTask(task, input, (d3) => {
      if (gone()) return;
      got = true;
      setComposer(textarea.value + d3);
    });
    if (gone()) {
      if (btn2) {
        btn2.disabled = false;
        if (original) btn2.innerHTML = original;
      }
      return;
    }
    if (btn2) {
      btn2.disabled = false;
      if (original) btn2.innerHTML = original;
    }
    if (!res.ok || !got && !res.text) {
      setComposer(prev);
      toast(res.message ?? t("Couldn't generate that."), "error");
      return;
    }
    if (!got && res.text) {
      setComposer(res.text);
    }
    setComposer(textarea.value.trim());
    textarea.focus();
  }

